// String prints human readable information.
func (tp Protocol) String() string {
	if tp == PurePayload {
		return "PurePayload"
	}

	// Map of individual flags to their names
	flags := []struct {
		bit  Protocol
		name string
	}{
		{TTHeader, "TTHeader"},
		{Framed, "Framed"},
		{HTTP, "HTTP"},
		{GRPC, "GRPC"},
		{HESSIAN2, "Hessian2"},
		{TTHeaderStreaming, "TTHeaderStreaming"},
		{GRPCStreaming, "GRPCStreaming"},
	}

	var parts []string
	for _, flag := range flags {
		if tp&flag.bit != 0 {
			parts = append(parts, flag.name)
		}
	}

	if len(parts) == 0 {
		return Unknown
	}

	// Join with pipe separator
	result := parts[0]
	for i := 1; i < len(parts); i++ {
		result += "|" + parts[i]
	}
	return result
}

