// TailOption is a special option type that applies after client initialization completes.
// It is useful for options that need to modify the client after all other options have been processed,
// such as wrapping middleware chains or applying post-configuration modifications.
//
// TailOptions are processed in order after all normal Options.
func TailOption(f func(o *client.Options)) Option {
	return Option{F: func(o *client.Options, di *utils.Slice) {
		di.Push("TailOption")
