// Example 1: Unary Middleware
// UnaryMiddleware applies only to unary (non-streaming) RPC calls.

func loggingUnaryMiddleware(next endpoint.Endpoint) endpoint.Endpoint {
	return func(ctx context.Context, req, resp interface{}) error {
		start := time.Now()
		methodName := "unary_call" // In real code, extract from rpcinfo

