// Example 4: StreamSend Middleware (Per-message send)
// StreamSendMiddleware intercepts each Send() operation on the stream.

type rateLimitSendMiddleware struct {
	maxPerSecond int
	lastSend     time.Time
}

func (m *rateLimitSendMiddleware) SendMiddleware(next streamx.SendHandler) streamx.SendHandler {
	return func(ctx context.Context, msg interface{}) error {
		// Simple rate limiting example
		if !m.lastSend.IsZero() {
			elapsed := time.Since(m.lastSend)
			minInterval := time.Second / time.Duration(m.maxPerSecond)
			if elapsed < minInterval {
				time.Sleep(minInterval - elapsed)
			}
		}

		log.Printf("[SendMW] Sending message with rate limit...")
		err := next(ctx, msg)
		m.lastSend = time.Now()
		return err
	}
}

// Example 5: Using the new option APIs

func createClientWithOptions() {
	// Create unary middleware
	unaryMW := endpoint.UnaryMiddleware(loggingUnaryMiddleware)

	// Create streaming middlewares
	streamMW := &loggingStreamMiddleware{}
	recvMW := &validationRecvMiddleware{}
	sendMW := &rateLimitSendMiddleware{maxPerSecond: 100}

	// Option 1: Apply unary options separately
	cli, err := client.NewClient(
		"demo-service",
		client.WithUnaryMiddleware(unaryMW),
		client.WithUnaryRPCTimeout(5*time.Second),
	)
	if err != nil {
		log.Fatal(err)
	}
	defer cli.Close()

	// Option 2: Batch apply unary options using WithUnaryOptions
	cli2, err := client.NewClient(
		"demo-service",
		client.WithUnaryOptions(
			client.WithUnaryMiddleware(unaryMW),
			client.WithUnaryRPCTimeout(5*time.Second),
		),
	)
	if err != nil {
		log.Fatal(err)
	}
	defer cli2.Close()

	// Option 3: Apply streaming options
	cli3, err := client.NewClient(
		"demo-service",
		client.WithStreamMiddleware(streamMW),
		client.WithStreamRecvMiddleware(recvMW),
		client.WithStreamSendMiddleware(sendMW),
		client.WithRecvTimeout(10*time.Second),
	)
	if err != nil {
		log.Fatal(err)
	}
	defer cli3.Close()

	// Option 4: Batch apply streaming options using WithStreamOptions
	cli4, err := client.NewClient(
		"demo-service",
		client.WithStreamOptions(
			client.WithStreamMiddleware(streamMW),
			client.WithStreamRecvMiddleware(recvMW),
			client.WithStreamSendMiddleware(sendMW),
		),
		client.WithRecvTimeout(10*time.Second),
	)
	if err != nil {
		log.Fatal(err)
	}
	defer cli4.Close()

	// Option 5: Mix unary and streaming options
	cli5, err := client.NewClient(
		"demo-service",
		// Unary options
		client.WithUnaryOptions(
			client.WithUnaryMiddleware(unaryMW),
			client.WithUnaryRPCTimeout(5*time.Second),
		),
		// Streaming options
		client.WithStreamOptions(
			client.WithStreamMiddleware(streamMW),
			client.WithStreamRecvMiddleware(recvMW),
			client.WithStreamSendMiddleware(sendMW),
		),
		client.WithRecvTimeout(10*time.Second),
	)
	if err != nil {
		log.Fatal(err)
	}
	defer cli5.Close()
}

