// =============================================================================
// Example 7: Chaining Multiple Middlewares
// =============================================================================

/*
Middlewares are applied right-to-left during client creation.
Execution order during runtime is left-to-right.

Example:
client.WithUnaryOptions(
	client.WithUnaryMiddleware(endpoint.UnaryMiddleware(LoggingUnaryMiddleware)),  // Applied last, executes first
	client.WithUnaryMiddleware(endpoint.UnaryMiddleware(MetricsMiddleware)),       // Applied second
	client.WithUnaryMiddleware(endpoint.UnaryMiddleware(AuthMiddleware)),          // Applied first, executes last
)

Execution order when making an RPC call:
1. LoggingUnaryMiddleware (logs start)
2. MetricsMiddleware (starts timer)
3. AuthMiddleware (checks auth)
4. Actual RPC call
5. AuthMiddleware (returns)
6. MetricsMiddleware (records duration)
7. LoggingUnaryMiddleware (logs end)
*/

// =============================================================================
// Example 8: Using endpoint.UnaryChain for Pre-composed Middleware
// =============================================================================

// CreateAuthenticatedLoggingMiddleware creates a pre-composed middleware chain.
func CreateAuthenticatedLoggingMiddleware() endpoint.UnaryMiddleware {
	return endpoint.UnaryChain(
		endpoint.UnaryMiddleware(LoggingUnaryMiddleware),
		endpoint.UnaryMiddleware(MetricsMiddleware),
		endpoint.UnaryMiddleware(AuthMiddleware),
	)
}

