// DecompressionRecvMiddleware decompresses each received message.
type DecompressionRecvMiddleware struct{}

func (m *DecompressionRecvMiddleware) RecvMiddleware(next cep.RecvHandler) cep.RecvHandler {
	return func(ctx context.Context, msg interface{}) (interface{}, error) {
		result, err := next(ctx, msg)
		if err != nil {
			return result, err
		}

