}

// =============================================================================
// Example 4: StreamSend Middleware (Per-message send)
// StreamSendMiddleware intercepts each Send() operation on the stream.
// =============================================================================

// RateLimitSendMiddleware limits the rate of outgoing messages.
type RateLimitSendMiddleware struct {
	maxPerSecond int
	lastSend     time.Time
}

func (m *RateLimitSendMiddleware) SendMiddleware(next cep.SendHandler) cep.SendHandler {
	return func(ctx context.Context, msg interface{}) error {
		// Simple rate limiting example
		if !m.lastSend.IsZero() {
			elapsed := time.Since(m.lastSend)
			minInterval := time.Second / time.Duration(m.maxPerSecond)
			if elapsed < minInterval {
				time.Sleep(minInterval - elapsed)
			}
		}

		log.Printf("[SendMW] Sending message with rate limit...")
		err := next(ctx, msg)
		m.lastSend = time.Now()
		return err
	}
}

// CompressionSendMiddleware compresses each outgoing message.
type CompressionSendMiddleware struct{}

func (m *CompressionSendMiddleware) SendMiddleware(next cep.SendHandler) cep.SendHandler {
	return func(ctx context.Context, msg interface{}) error {
		log.Printf("[SendMW] Compressing message before send...")
		// Compress logic here

		return next(ctx, msg)
	}
}

