// Example 5: Using WithUnaryOptions and WithStreamOptions
// =============================================================================

/*
Usage in client creation:

import (
	"github.com/cloudwego/kitex/client"
	"github.com/cloudwego/kitex/pkg/endpoint"
)

// Example 1: Apply unary options separately
cli, err := client.NewClient(
	serviceInfo,
	client.WithUnaryMiddleware(endpoint.UnaryMiddleware(LoggingUnaryMiddleware)),
	client.WithUnaryRPCTimeout(5*time.Second),
)

// Example 2: Batch apply unary options using WithUnaryOptions
cli, err := client.NewClient(
	serviceInfo,
	client.WithUnaryOptions(
		client.WithUnaryMiddleware(endpoint.UnaryMiddleware(LoggingUnaryMiddleware)),
		client.WithUnaryMiddleware(endpoint.UnaryMiddleware(AuthMiddleware)),
		client.WithUnaryRPCTimeout(5*time.Second),
	),
)

// Example 3: Apply streaming options
streamMW := &LoggingStreamMiddleware{}
recvMW := &ValidationRecvMiddleware{}
sendMW := &RateLimitSendMiddleware{maxPerSecond: 100}

cli, err := client.NewClient(
	serviceInfo,
	client.WithStreamMiddleware(streamMW),
	client.WithStreamRecvMiddleware(recvMW),
	client.WithStreamSendMiddleware(sendMW),
