// =============================================================================
// Example 6: Context-aware Middleware using MiddlewareBuilder
// =============================================================================

// ContextAwareMiddlewareBuilder creates middleware that uses context values.
func ContextAwareMiddlewareBuilder(ctx context.Context) endpoint.Middleware {
	// Extract context values at middleware construction time
	requestID, _ := ctx.Value("request_id").(string)

	return func(next endpoint.Endpoint) endpoint.Endpoint {
		return func(ctx context.Context, req, resp interface{}) error {
			log.Printf("[ContextMW] Processing request_id=%s", requestID)
			return next(ctx, req, resp)
		}
	}
}

/*
Usage with middleware builder:

cli, err := client.NewClient(
	serviceInfo,
	client.WithUnaryMiddlewareBuilder(
		endpoint.UnaryMiddlewareBuilder(ContextAwareMiddlewareBuilder),
	),
)
*/

// =============================================================================
// Example 7: Chaining Multiple Middlewares
// =============================================================================

/*
Middlewares are applied right-to-left during client creation.
Execution order during runtime is left-to-right.

Example:
client.WithUnaryOptions(
	client.WithUnaryMiddleware(endpoint.UnaryMiddleware(LoggingUnaryMiddleware)),  // Applied last, executes first
	client.WithUnaryMiddleware(endpoint.UnaryMiddleware(MetricsMiddleware)),       // Applied second
	client.WithUnaryMiddleware(endpoint.UnaryMiddleware(AuthMiddleware)),          // Applied first, executes last
)

Execution order when making an RPC call:
1. LoggingUnaryMiddleware (logs start)
2. MetricsMiddleware (starts timer)
3. AuthMiddleware (checks auth)
4. Actual RPC call
5. AuthMiddleware (returns)
6. MetricsMiddleware (records duration)
7. LoggingUnaryMiddleware (logs end)
*/

// =============================================================================
// Example 8: Using endpoint.UnaryChain for Pre-composed Middleware
// =============================================================================

// CreateAuthenticatedLoggingMiddleware creates a pre-composed middleware chain.
func CreateAuthenticatedLoggingMiddleware() endpoint.UnaryMiddleware {
	return endpoint.UnaryChain(
		endpoint.UnaryMiddleware(LoggingUnaryMiddleware),
		endpoint.UnaryMiddleware(MetricsMiddleware),
		endpoint.UnaryMiddleware(AuthMiddleware),
	)
}

/*
Usage with pre-composed middleware:

composedMW := CreateAuthenticatedLoggingMiddleware()
cli, err := client.NewClient(
	serviceInfo,
	client.WithUnaryMiddleware(composedMW),
)
*/

// =============================================================================
// Key Concepts Summary
// =============================================================================

/*
1. UnaryMiddleware vs StreamMiddleware:
   - UnaryMiddleware: For single request-response calls
   - StreamMiddleware: For streaming calls (wraps entire stream lifecycle)

2. StreamRecvMiddleware vs StreamSendMiddleware:
   - StreamRecvMiddleware: Intercepts each Recv() operation
   - StreamSendMiddleware: Intercepts each Send() operation

3. Option Batching:
   - WithUnaryOptions(): Group multiple unary options together
   - WithStreamOptions(): Group multiple streaming options together

4. Middleware Execution Order:
   - Options are applied right-to-left during client creation
   - Middleware executes left-to-right during runtime
   - Use endpoint.UnaryChain() to pre-compose middleware chains

5. Context-aware Middleware:
   - Use MiddlewareBuilder to access context values at construction time
   - Use WithUnaryMiddlewareBuilder() to register builders

6. Tail Functions:
   - tail_xxx options (like tail_ttstream) are automatically chained
   - Applied after all other options to ensure proper initialization order
*/

