// Dump returns a JSON-serializable snapshot of the connection pool state.
// The returned map uses remote addresses as keys and connection information as values.
// This method is panic-safe and will return partial results if any address fails.
func (p *connPool) Dump() interface{} {
	result := make(map[string]interface{})

	p.conns.Range(func(key, value interface{}) bool {
		defer func() {
			if r := recover(); r != nil {
				// If panic occurs, log it but continue processing other connections
				addr := key.(string)
				result[addr] = map[string]interface{}{
					"error": "panic during dump",
					"panic": r,
				}
			}
		}()

		addr := key.(string)
		trans := value.(*transports)

		connInfo := make(map[string]interface{})
		connInfo["pool_size"] = trans.size
		connInfo["current_index"] = atomic.LoadUint32(&trans.index)

		// Collect information about each connection in the pool
		connections := make([]map[string]interface{}, 0, trans.size)
		for i := 0; i < int(trans.size); i++ {
			cliTransport := trans.cliTransports[i]
			connState := map[string]interface{}{
				"slot": i,
			}
			if cliTransport == nil {
				connState["status"] = "empty"
			} else if cliTransport.(grpc.IsActive).IsActive() {
				connState["status"] = "active"
			} else {
				connState["status"] = "inactive"
			}
			connections = append(connections, connState)
		}
		connInfo["connections"] = connections

		result[addr] = connInfo
		return true
	})

	return result
}

